    return [[min(v for row in grid for v in row)]]"},{"nl":"Return the value at the bottom-right corner.","code":"def transform(grid):
    return [[grid[-1][-1]]]"},{"nl":"Return the count of zeros modulo 10.","code":"def transform(grid):
    return [[sum(v == 0 for row in grid for v in row) % 10]]"},{"nl":"Return the number of cells equal to the bottom-right value, modulo 10.","code":"def transform(grid):
    x = grid[-1][-1]
    return [[sum(v == x for row in grid for v in row) % 10]]"},{"nl":"Return the minimum value on the border.","code":"def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [grid[r][c] for r in range(h) for c in range(w) if r in (0,h-1) or c in (0,w-1)]
    return [[min(vals)]]"},{"nl":"Return the value in the center cell for odd-sized square grids.","code":"def transform(grid):
    return [[grid[len(grid)//2][len(grid[0])//2]]]"},{"nl":"Return the sum of the main diagonal modulo 3.","code":"def transform(grid):
    return [[sum(grid[i][i] for i in range(min(len(grid), len(grid[0])))) % 3]]"},{"nl":"Return the count of cells whose value is less than 1.","code":"def transform(grid):
    return [[sum(v < 1 for row in grid for v in row)]]"},{"nl":"Return the minimum of the four corner values.","code":"def transform(grid):
    return [[min(grid[0][0], grid[0][-1], grid[-1][0], grid[-1][-1])]]"},{"nl":"Return the number of distinct values minus the number of rows, clamped at zero.","code":"def transform(grid):
    return [[max(0, len(set(v for row in grid for v in row)) - len(grid))]]"}]}

